const dados = $('Chamado pela FUP').first().json;
const nome = (dados.nome || '').trim() || 'Lead sem nome no cadastro';
const telefone = dados.telefone;
const motivo = (dados.motivo || '').trim();
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit' });
const texto =
  '\u{1F7E1} *LEAD INTERESSADO - PAROU DE RESPONDER*\n' +
  'A IA identificou sinais de interesse, mas o lead parou de responder durante a cadencia de lembretes.\n\n' +
  '*Lead:* ' + nome + '\n' +
  '*WhatsApp:* +' + telefone + '\n' +
  (dados.email ? '*E-mail:* ' + dados.email + '\n' : '') +
  (motivo ? '*Por que a IA avaliou como interessado:* ' + motivo + '\n' : '') +
  '*Horario do aviso:* ' + agora + '\n\n' +
  'Etapa no kanban: Interessado - Transferir Humano\n' +
  'Origem: SDR Outbound - FUP';
return [{ json: { nome, telefone, email: dados.email || null, motivo, texto } }];
